### 2.5 클래스 위임 (Interface Delegation)

프로퍼티 위임이 **프로퍼티 수준**의 위임이라면, 클래스 위임은 **인터페이스 구현 수준**의 위임이다.

#### 기본 개념

```kotlin
interface Printer {
    fun print(message: String)
}

class ConsolePrinter : Printer {
    override fun print(message: String) = println("[Console] $message")
}

// ConsolePrinter에게 Printer 구현을 위임
class PrefixPrinter(
    private val prefix: String,
    printer: Printer
) : Printer by printer {
    // print()를 직접 구현하지 않아도 printer의 print()가 호출됨
    // 필요한 메서드만 오버라이드 가능
}
```

#### 왜 상속 대신 클래스 위임인가?

Java에서 데코레이터 패턴을 구현하려면 모든 메서드를 일일이 위임해야 한다:

```java
// Java: 모든 메서드를 수동 위임해야 함 (보일러플레이트 지옥)
public class LoggingUserRepository implements UserRepository {
    private final UserRepository delegate;

    public LoggingUserRepository(UserRepository delegate) {
        this.delegate = delegate;
    }

    @Override
    public User findById(Long id) {
        return delegate.findById(id);  // 단순 위임
    }

    @Override
    public User save(User user) {
        logger.info("Saving user: " + user.getName());
        User saved = delegate.save(user);
        logger.info("Saved user with id: " + saved.getId());
        return saved;
    }

    @Override
    public void deleteById(Long id) {
        delegate.deleteById(id);  // 단순 위임
    }

    // 인터페이스에 메서드가 추가되면... 여기도 추가해야 함!
}
```

Kotlin은 `by` 키워드로 이 문제를 언어 수준에서 해결한다:

```kotlin
interface UserRepository {
    fun findById(id: Long): User?
    fun save(user: User): User
    fun deleteById(id: Long)
    fun findAll(): List<User>
    fun count(): Long
}

// Kotlin: 수정하고 싶은 메서드만 오버라이드
class LoggingUserRepository(
    private val delegate: UserRepository
) : UserRepository by delegate {

    private val logger = LoggerFactory.getLogger(javaClass)

    // save만 오버라이드하여 로깅 추가
    override fun save(user: User): User {
        logger.info("Saving user: ${user.name}")
        val saved = delegate.save(user)
        logger.info("Saved user with id: ${saved.id}")
        return saved
    }

    // findById, deleteById, findAll, count는 자동으로 delegate에 위임!
    // 인터페이스에 새 메서드가 추가되어도 자동 위임됨!
}
```

#### 클래스 위임 활용: 다중 기능 합성

클래스 위임을 사용하면 **여러 인터페이스의 구현을 합성**할 수 있다:

```kotlin
interface Logger {
    fun log(message: String)
}

interface MetricsCollector {
    fun recordLatency(operation: String, millis: Long)
    fun incrementCounter(name: String)
}

class ConsoleLogger : Logger {
    override fun log(message: String) = println("[LOG] $message")
}

class PrometheusMetrics : MetricsCollector {
    override fun recordLatency(operation: String, millis: Long) {
        println("[METRIC] $operation: ${millis}ms")
    }
    override fun incrementCounter(name: String) {
        println("[METRIC] $name++")
    }
}

// 여러 인터페이스의 구현을 합성
class InstrumentedService(
    logger: Logger,
    metrics: MetricsCollector
) : Logger by logger, MetricsCollector by metrics {

    fun processOrder(orderId: String) {
        val start = System.currentTimeMillis()
        log("Processing order: $orderId")            // Logger에서 위임
        incrementCounter("orders.processed")          // MetricsCollector에서 위임

        // ... 비즈니스 로직 ...

        val elapsed = System.currentTimeMillis() - start
        recordLatency("processOrder", elapsed)        // MetricsCollector에서 위임
    }
}
```

